-- MP-0006: guarded editorial content import. Deploy portraits before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='bersatu' and type='party') then raise exception 'MP-0006: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0006: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('hassan-saad','azman-nasrudin','roslan-hashim') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0006: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('baling','padang serai','kulim bandar baharu') and slug not in ('hassan-saad','azman-nasrudin','roslan-hashim')) then raise exception 'MP-0006: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0006:%' and (m.source_type <> 'editorial' or e.slug not in ('hassan-saad','azman-nasrudin','roslan-hashim') or m.import_key not like 'MP-0006:' || e.slug || ':%')) then raise exception 'MP-0006: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'hassan-saad','Hassan Saad','opposition','Member of the Dewan Rakyat','Baling','Kedah','Hassan Saad represents Baling, Kedah, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4055','/portraits/hassan-saad.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P016.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4055"}, {"label": "PAS · current parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'azman-nasrudin','Azman Nasrudin','opposition','Member of the Dewan Rakyat','Padang Serai','Kedah','Azman Nasrudin represents Padang Serai, Kedah, in the Dewan Rakyat. A Bersatu member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4056','/portraits/azman-nasrudin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P017.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4056"}, {"label": "Reported Bersatu affiliation · 29 Oct 2026 CSA signatories", "url": "https://bernama.com/bm/am/news.php?id=2627381"}]'::jsonb from public.entities parent where parent.slug='bersatu' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'roslan-hashim','Roslan Hashim','opposition','Member of the Dewan Rakyat','Kulim Bandar Baharu','Kedah','Roslan Hashim represents Kulim Bandar Baharu, Kedah, in the Dewan Rakyat. A Bersatu member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4057','/portraits/roslan-hashim.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P018.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4057"}, {"label": "Reported Bersatu affiliation · 20 Oct 2026 statement", "url": "https://harakahdaily.net/2026/10/20/belum-tamat-notis-ros-sudah-batal-pn/"}]'::jsonb from public.entities parent where parent.slug='bersatu' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('hassan-saad','azman-nasrudin','roslan-hashim') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0006: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0006:hassan-saad:constituency-outreach','Provide welfare visits and support across Baling’s three state constituencies','Social welfare','in_progress',null,null,null,null,'2024-07-30','https://harakahdaily.net/2024/07/30/ustaz-hassan-saad-menjengah-ke-teratak-rakyat/','The report documents Hassan’s outreach in Kupang, Kuala Ketil and Bayu, including help for residents facing hardship.','This is a July 2024 snapshot of continuing constituency work. State rice and food-basket support is credited as shared assistance. Later coverage, expenditure and a completion denominator were not verified.','2026-11-09','editorial',false from public.entities e where e.slug='hassan-saad' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0006:azman-nasrudin:budget-2027-csa','Support Budget 2027 under the CSA','Governance',null,null,null,'2026-10-29','https://bernama.com/bm/am/news.php?id=2627381',null,null,'The MP was a named agreement signatory.','Signing is documented; subsequent budget votes were not verified. Outcome and completion remain unknown.','2026-11-09','editorial',false from public.entities e where e.slug='azman-nasrudin' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

